package com.company.tpm.telegram;import com.company.tpm.config.AppProperties;import java.util.Map;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class TelegramBotClient{private final AppProperties props;private final RestClient http=RestClient.create();public TelegramBotClient(AppProperties p){props=p;}public void send(long chatId,String text){if(!props.telegram().enabled())return;if(props.telegram().botToken()==null||props.telegram().botToken().isBlank())throw new IllegalStateException("Telegram token is required when enabled");http.post().uri("https://api.telegram.org/bot"+props.telegram().botToken()+"/sendMessage").body(Map.of("chat_id",chatId,"text",text)).retrieve().toBodilessEntity();}}
